-- Run on a disposable local database after migrations; all fixtures roll back.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path = public, extensions;
SELECT no_plan();
SELECT set_config('request.jwt.claims', '{"role":"service_role"}', true);
INSERT INTO public.categories (id, name) VALUES ('44111111-0000-0000-0000-000000000001', 'binding test');
INSERT INTO public.menu_items (id, category_id, name, price_cents) VALUES ('44111111-0000-0000-0000-000000000002', '44111111-0000-0000-0000-000000000001', 'binding test', 100), ('44111111-0000-0000-0000-000000000008', '44111111-0000-0000-0000-000000000001', 'second item', 100);
INSERT INTO public.modifier_groups (id, name) VALUES ('44111111-0000-0000-0000-000000000003', 'old group'), ('44111111-0000-0000-0000-000000000004', 'new group'), ('44111111-0000-0000-0000-000000000005', 'replacement group');
INSERT INTO public.modifier_groups (id, name, min_selections) VALUES ('44111111-0000-0000-0000-000000000006', 'min group without options', 1), ('44111111-0000-0000-0000-000000000007', 'min group with option', 1);
INSERT INTO public.modifiers (modifier_group_id, name) VALUES ('44111111-0000-0000-0000-000000000003', 'old option'), ('44111111-0000-0000-0000-000000000005', 'replacement option'), ('44111111-0000-0000-0000-000000000007', 'min option');
INSERT INTO public.menu_item_modifier_groups (menu_item_id, modifier_group_id, is_required) VALUES ('44111111-0000-0000-0000-000000000002', '44111111-0000-0000-0000-000000000003', true);
CREATE TEMP TABLE binding_refresh AS SELECT count(*) AS queued FROM public.grabfood_menu_refresh;

SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims', '{}', true);
SELECT throws_ok($$SELECT * FROM public.replace_item_modifier_groups('44111111-0000-0000-0000-000000000002', '[]'::jsonb)$$, '42501', NULL, 'missing claims cannot clear bindings');
SELECT set_config('request.jwt.claims', '{"sub":"aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa","role":"authenticated","app_metadata":{"role":"cashier"}}', true);
SELECT throws_ok($$SELECT * FROM public.replace_item_modifier_groups('44111111-0000-0000-0000-000000000002', '[]'::jsonb)$$, '42501', NULL, 'cashier cannot clear bindings');
SELECT set_config('request.jwt.claims', '{"sub":"aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa","role":"authenticated","app_metadata":{"role":"admin"}}', true);
SELECT throws_ok($$SELECT * FROM public.replace_item_modifier_groups('44111111-0000-0000-0000-000000000002', '[{"modifier_group_id":"44111111-0000-0000-0000-000000000004"},{"modifier_group_id":"44111111-0000-0000-0000-000000000004"}]'::jsonb)$$, '22023', NULL, 'duplicate group ids are rejected before mutating');
SELECT throws_ok($$SELECT * FROM public.replace_item_modifier_groups('44111111-0000-0000-0000-000000000002', '[{"modifier_group_id":"44111111-0000-0000-0000-000000000009","is_required":false}]'::jsonb)$$, '23503', NULL, 'unknown group fails');
SELECT throws_ok($$SELECT * FROM public.replace_item_modifier_groups('44111111-0000-0000-0000-000000000002', '[{"modifier_group_id":"44111111-0000-0000-0000-000000000004","is_required":true}]'::jsonb)$$, '23514', NULL, 'required group without an available option fails');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.menu_item_modifier_groups WHERE menu_item_id='44111111-0000-0000-0000-000000000002' AND modifier_group_id='44111111-0000-0000-0000-000000000003' AND is_required), 1::bigint, 'old binding survives denied and failed replacement');
SELECT is((SELECT count(*) FROM public.grabfood_menu_refresh), (SELECT queued FROM binding_refresh), 'failed replacement rolls back Grab refresh trigger');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT * FROM public.replace_item_modifier_groups('44111111-0000-0000-0000-000000000002', '[{"modifier_group_id":"44111111-0000-0000-0000-000000000006","is_required":false}]'::jsonb)$$, '23514', NULL, 'min_selections group without an available option fails even when optional');
SELECT lives_ok($$SELECT * FROM public.replace_item_modifier_groups('44111111-0000-0000-0000-000000000008', '[{"modifier_group_id":"44111111-0000-0000-0000-000000000007","is_required":false}]'::jsonb)$$, 'min_selections group with an available option accepts an optional binding');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.menu_item_modifier_groups WHERE menu_item_id='44111111-0000-0000-0000-000000000008' AND modifier_group_id='44111111-0000-0000-0000-000000000007' AND NOT is_required), 1::bigint, 'optional binding to a min_selections group is saved');
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT * FROM public.replace_item_modifier_groups('44111111-0000-0000-0000-000000000002', '[{"modifier_group_id":"44111111-0000-0000-0000-000000000004","is_required":false}]'::jsonb)$$, 'admin can replace bindings');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.menu_item_modifier_groups WHERE menu_item_id='44111111-0000-0000-0000-000000000002' AND modifier_group_id='44111111-0000-0000-0000-000000000004' AND NOT is_required), 1::bigint, 'new binding is saved');
SELECT is((SELECT count(*) FROM public.menu_item_modifier_groups WHERE menu_item_id='44111111-0000-0000-0000-000000000002' AND modifier_group_id='44111111-0000-0000-0000-000000000003'), 0::bigint, 'old binding is removed');
SELECT ok((SELECT count(*) FROM public.grabfood_menu_refresh) > (SELECT queued FROM binding_refresh), 'successful replacement enqueues Grab refresh');
SELECT set_config('request.jwt.claims', '{"role":"service_role"}', true);
DELETE FROM public.modifier_groups WHERE id='44111111-0000-0000-0000-000000000003';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims', '{"sub":"aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa","role":"authenticated","app_metadata":{"role":"admin"}}', true);
SELECT throws_ok($$SELECT * FROM public.replace_item_modifier_groups('44111111-0000-0000-0000-000000000002', '[{"modifier_group_id":"44111111-0000-0000-0000-000000000003","is_required":true}]'::jsonb)$$, '23503', NULL, 'archived group cannot be rebound');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.menu_item_modifier_groups WHERE menu_item_id='44111111-0000-0000-0000-000000000002' AND modifier_group_id='44111111-0000-0000-0000-000000000004'), 1::bigint, 'stale group does not remove existing binding');
SELECT set_config('request.jwt.claims', '{"role":"service_role"}', true);
DELETE FROM public.menu_items WHERE id='44111111-0000-0000-0000-000000000002';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims', '{"sub":"aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa","role":"authenticated","app_metadata":{"role":"admin"}}', true);
SELECT throws_ok($$SELECT * FROM public.replace_item_modifier_groups('44111111-0000-0000-0000-000000000002', '[]'::jsonb)$$, '23514', NULL, 'archived item cannot receive bindings');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
